import XCTest
@MainActor
final class CheckoutTests: XCTestCase {
    func testConfirm() {
        let app = XCUIApplication()
        app.launchArguments = ["--ui-testing", "--fixture=checkout-ready"]
        app.launch()
        let button = app.buttons["checkout.confirm"]
        guard button.waitForExistence(timeout: 3) else {
            XCTFail("Нет checkout.confirm")
            return
        }
        button.tap()
        let state = app.staticTexts["checkout.state"]
        XCTAssertTrue(waitForText("Сохранено", element: state))
    }
}
func waitForText(_ text: String, element: XCUIElement) -> Bool {
    let predicate = NSPredicate(format: "label == %@", text)
    let expectation = XCTNSPredicateExpectation(
        predicate: predicate, object: element
    )
    return XCTWaiter.wait(for: [expectation], timeout: 3) == .completed
}

Ожидание label отделяет эффект от существования элемента. Успех требует завершённого сохранения, а не наличия прежней строки.

enum SessionFixture: Equatable { case live, ready }
struct SessionConfig {
    static func fixture(arguments: [String]) -> SessionFixture {
        guard arguments.contains("--ui-testing"),
              arguments.contains("--fixture=session-ready") else {
            return .live
        }
        return .ready
    }
}
import XCTest
final class ConfigTests: XCTestCase {
    func testRequiresOptIn() {
        XCTAssertEqual(SessionConfig.fixture(arguments: [
            "--fixture=session-ready"
        ]), .live)
        XCTAssertEqual(SessionConfig.fixture(arguments: [
            "--ui-testing", "--fixture=session-ready"
        ]), .ready)
        XCTAssertEqual(SessionConfig.fixture(arguments: []), .live)
    }
}

Конфигурация требует два условия одновременно. Этот unit-тест проверяет обработчик аргументов; ни одно его утверждение не доказывает работу accessibility-дерева.
